test("a count nobody took is shown as words, never as a zero", async ({ page }) => {
  await openReports(page, fixtures().director);
  await openNewestReport(page);

  const till = page.getByRole("region", { name: /cashier's cash count/i });
  await expect(till).toBeVisible();

  // The chip is on the heading, so it is readable before the section is opened at all.
  await expect(till.getByText(/^not counted$/i)).toBeVisible();

  await openSection(page, "cashierReconciliation");
  await expect(till.getByText(/nobody counted the till/i)).toBeVisible();

  // The three figures are absent, and each says so. `TZS 0` anywhere in this card would mean the
  // screen had told a Director the till balanced on a night nobody opened it.
  await expect(till.getByText(/not recorded/i)).toHaveCount(3);
  await expect(till.getByText(/TZS/)).toHaveCount(0);
});

/**
 * Issue #51 · Imprest spending does not exist on main, so its figures are WITHHELD — a different
 * fact from "not recorded", worded differently and explained, and never a zero or a balance.
 */
test("imprest figures the system cannot give yet say so, and are never a zero", async ({ page }) => {
  await openReports(page, fixtures().director);
  await openNewestReport(page);

  const balance = page.getByRole("region", { name: /imprest balance/i });
  await openSection(page, "imprestPosition");
  await expect(balance.getByText(/^not available$/i)).toHaveCount(4);
  await expect(balance.getByText(/imprest spending is not in the system yet/i)).toBeVisible();
  await expect(balance.getByText(/TZS/)).toHaveCount(0);

  const expenses = page.getByRole("region", { name: /approved imprest expenses/i });
  await openSection(page, "imprestExpenses");
  await expect(expenses.getByText(/^not available$/i)).toHaveCount(2);
  await expect(expenses.getByText(/TZS/)).toHaveCount(0);
});

