test("the archive shows a skeleton shaped like it before the reports arrive", async ({
  page,
}, testInfo) => {
  const { director } = fixtures();
  await signIn(page, director.phone, director.password);
  await expectLandsOn(page, "/dashboard");

  // The prefetch is let through and the real navigation is slowed. Delaying everything would slow
  // the prefetch instead, and the click would then be served from a cache that arrived late — which
  // proves nothing about what a person sees while they wait.
  let seen = 0;
  await page.route(/\/reports/, async (route) => {
    seen += 1;
    if (seen > 1) await new Promise((resolve) => setTimeout(resolve, 3000));
    await route.continue();
  });

  const navigation = await openNavigation(page, testInfo);
  // `noWaitAfter`, because the click otherwise returns only once the navigation has settled — and
  // by then the skeleton this test exists to see has already been replaced by the page.
  await navigation.getByRole("link", { name: REPORTS_HEADING }).click({ noWaitAfter: true });

  const skeleton = page.getByRole("status");
  await expect(skeleton).toBeVisible({ timeout: 5000 });
  await expect(skeleton).toContainText(/working/i);

  // Shaped like the archive it stands in for: a card per day, and each card carrying the five
  // things a loaded card carries — the business date, how many people it reached, when it was
  // written, the integrity chip and the word that opens it (design.md §12.7 rule 3). A skeleton
  // promising fewer is a page that jumps as the rest arrives.
  const cards = skeleton.getByTestId("report-card-skeleton");
  await expect(cards).toHaveCount(5);
  for (const card of await cards.all()) {
    await expect(card.locator("[data-slot='skeleton']")).toHaveCount(5);
  }

  await expect(page.getByRole("heading", { name: REPORTS_HEADING })).toBeVisible({
    timeout: 20_000,
  });
});

test("a read the database refuses is stated as a failure, and the retry re-runs it", async ({
  page,
}) => {
  const { director } = fixtures();
  await signIn(page, director.phone, director.password);
  await expectLandsOn(page, "/dashboard");

  // The archive is there and readable, so what follows is a failure and not an empty night.
  await page.goto("/reports");
  await expect(page.locator("[data-testid^='report-']").first()).toBeVisible();

  try {
    revokeReportRead();
    await page.goto("/reports");

    // §12.5's third kind of error: page-level, because there is no content to attach it to.
    const alert = page
      .getByRole("alert")
      .filter({ has: page.getByRole("button", { name: /try again/i }) });
    await expect(alert).toBeVisible();
    await expect(alert).toContainText(/the system could not be reached/i);
    await expect(alert).toContainText(/nothing you did was lost, and nothing was changed/i);
    await expect(page.getByRole("heading", { name: /could not be loaded/i })).toBeVisible();

    // THE ASSERTION THIS TEST EXISTS FOR. "No report has been written yet" during an outage would
    // tell a Director the business produced nothing last night. There is also no half-page: the
    // archive's own heading and its cards are gone, not merely empty.
    await expect(page.getByText(/no report has been written yet/i)).toHaveCount(0);
    await expect(page.locator("[data-testid^='report-']")).toHaveCount(0);
  } finally {
    // Whatever happened above, the next test meets a working database.
    restoreReportRead();
  }

  // A retry re-runs the read that failed, rather than clearing the message and showing the same
  // dead page (§12.7 rule 7). The database answers again, so the archive comes back.
  await page.getByRole("button", { name: /try again/i }).click();
  await expect(page.getByRole("heading", { name: REPORTS_HEADING })).toBeVisible({
    timeout: 20_000,
  });
  await expect(page.locator("[data-testid^='report-']").first()).toBeVisible();
});

test("on a phone the report opens as a summary with its sections shut", async ({ page }) => {
  await openReports(page, fixtures().director);
  await openNewestReport(page);

  const overview = page.getByRole("region", { name: /at a glance/i });
  await expect(overview).toBeVisible();
  // It names what is unresolved rather than counting it, so the reader is not sent hunting.
  await expect(overview).toContainText(/still unresolved/i);

  const body = page.locator("#report-section-sales");
  const toggle = page.getByTestId("report-toggle-sales");

  // A phone is below `md`, so the sections start shut; a tablet and a desktop are above it and
  // start open. One markup, one CSS rule, three tiers.
  const phone = test.info().project.name === "mobile";
  await expect(body).toBeVisible({ visible: !phone });
  await expect(toggle).toHaveAttribute("aria-expanded", phone ? "false" : "true");

  // Shut or open, an unresolved count is legible without pressing anything (§18.2a).
  await expect(page.getByTestId("report-toggle-cashierReconciliation")).toContainText(
    /not counted/i,
  );

  await toggle.click();
  await expect(body).toBeVisible({ visible: phone });
  await expect(toggle).toHaveAttribute("aria-expanded", phone ? "true" : "false");
});

