/**
 * Issue #19, F4 · Try again is pending until the refresh it started actually settles (§12.7).
 *
 * `retry()` returns at once, and the refreshed server content arrives later. Here the refresh is
 * HELD at the network: every non-prefetch RSC request for `/reports` waits until the test releases
 * it, so "pending" is observed for as long as the refresh is really unanswered, not for however
 * long a fast local server happens to take. The read fails where it really fails, with the grant on
 * the alert view withdrawn, and recovers when the grant comes back.
 */
test("Try again stays pending and single until the held refresh settles, then fails again or recovers", async ({
  page,
}) => {
  seedTerminalReportFailure(FAILED_NIGHT);

  const held: Array<() => void> = [];
  let refreshes = 0;

  try {
    await openReports(page, fixtures().director);
    await expect(page.getByTestId("missing-report-alerts")).toBeVisible();

    revokeReportAlertRead();
    await page.goto("/reports");

    // By its message, not by the button's name: the button is renamed while it is pending.
    const failure = page
      .getByRole("alert")
      .filter({ hasText: /the system could not be reached/i });
    await expect(failure).toBeVisible();

    // By its slot inside the failure, not by name: a pending Button is announced as "Working…", so
    // a name-based locator would stop matching exactly when the pending state is being asserted.
    const retry = failure.locator("button[data-slot='button']");
    await expect(retry).toHaveAccessibleName(/try again/i);
    const before = await retry.boundingBox();
    expect(before).not.toBeNull();

    await page.route(
      (url) => url.pathname === "/reports",
      async (route, request) => {
        const headers = request.headers();
        if (request.method() !== "GET" || headers["rsc"] !== "1" || headers["next-router-prefetch"]) {
          return route.continue();
        }
        refreshes += 1;
        await new Promise<void>((release) => held.push(release));
        await route.continue().catch(() => {});
      },
    );

    // FIRST ATTEMPT: pending at once, the same size, and announced for what it is doing.
    await retry.click();
    await expect.poll(() => held.length).toBe(1);
    await expect(retry).toHaveAttribute("aria-busy", "true");
    await expect(retry).toBeDisabled();
    await expect(retry).toHaveAccessibleName(/working/i);
    const during = await retry.boundingBox();
    expect(Math.abs(during!.width - before!.width)).toBeLessThan(0.5);
    expect(Math.abs(during!.height - before!.height)).toBeLessThan(0.5);

    // Pressed again while the refresh is held: nothing new is requested.
    const centre = { x: during!.x + during!.width / 2, y: during!.y + during!.height / 2 };
    await page.mouse.click(centre.x, centre.y);
    await page.mouse.click(centre.x, centre.y);
    await page.waitForTimeout(500);
    expect(refreshes).toBe(1);
    await expect(retry).toHaveAttribute("aria-busy", "true");

    // The held refresh is answered, and the read is still refused: the failure stays, and the
    // control is live again for a fresh, deliberate retry.
    held[0]!();
    await expect(retry).not.toHaveAttribute("aria-busy", "true");
    await expect(retry).toBeEnabled();
    await expect(retry).toHaveAccessibleName(/try again/i);
    await expect(failure).toContainText(/the system could not be reached/i);
    await expect(page.getByTestId("missing-report-alerts")).toHaveCount(0);

    // SECOND ATTEMPT: guarded in the same way, and this time the database answers.
    await retry.click();
    await expect.poll(() => held.length).toBe(2);
    await expect(retry).toHaveAttribute("aria-busy", "true");
    await expect(retry).toBeDisabled();
    expect(refreshes).toBe(2);

    restoreReportAlertRead();
    held[1]!();

    await expect(page.getByRole("heading", { name: REPORTS_HEADING })).toBeVisible({
      timeout: 20_000,
    });
    await expect(page.getByTestId(`missing-report-alert-${FAILED_NIGHT}`)).toBeVisible();
    await expect(failure).toHaveCount(0);
    expect(refreshes).toBe(2);
  } finally {
    for (const release of held) release();
    await page.unrouteAll({ behavior: "ignoreErrors" });
    restoreReportAlertRead();
    clearTerminalReportFailure(FAILED_NIGHT);
  }
});

/**
 * Issue #51 · The same F4 guard on a route that is NOT a report.
 *
 * `app/(app)/error.tsx` is the shell's one error boundary, so the pending retry changes every screen
 * under it, not only the report archive. This proves it on the imprest funding screen: the read is
 * refused where it really fails (the grant on `imprest_funding_position` is withdrawn, as
 * `imprest-funding.spec.ts` already does), the refresh is held at the network, and the control stays
 * pending, the same size and single until that refresh settles.
 */
test("Try again on a non-report screen is pending and single until its held refresh settles", async ({
  page,
}) => {
  const held: Array<() => void> = [];
  let refreshes = 0;

  try {
    const { director } = fixtures();
    await signIn(page, director.phone, director.password);
    await expectLandsOn(page, "/dashboard");

    runSql("revoke select on public.imprest_funding_position from authenticated;");
    await page.goto("/imprest");

    const failure = page
      .getByRole("alert")
      .filter({ hasText: /the system could not be reached/i });
    await expect(failure).toBeVisible();
    const retry = failure.locator("button[data-slot='button']");
    await expect(retry).toHaveAccessibleName(/try again/i);
    const before = await retry.boundingBox();
    expect(before).not.toBeNull();

    await page.route(
      (url) => url.pathname === "/imprest",
      async (route, request) => {
        const headers = request.headers();
        if (request.method() !== "GET" || headers["rsc"] !== "1" || headers["next-router-prefetch"]) {
          return route.continue();
        }
        refreshes += 1;
        await new Promise<void>((release) => held.push(release));
        await route.continue().catch(() => {});
      },
    );

    await retry.click();
    await expect.poll(() => held.length).toBe(1);
    await expect(retry).toHaveAttribute("aria-busy", "true");
    await expect(retry).toBeDisabled();
    const during = await retry.boundingBox();
    expect(Math.abs(during!.width - before!.width)).toBeLessThan(0.5);
    expect(Math.abs(during!.height - before!.height)).toBeLessThan(0.5);

    const centre = { x: during!.x + during!.width / 2, y: during!.y + during!.height / 2 };
    await page.mouse.click(centre.x, centre.y);
    await page.waitForTimeout(500);
    expect(refreshes).toBe(1);

    // Still refused: the failure stays and the control is live for a deliberate retry.
    held[0]!();
    await expect(retry).toBeEnabled();
    await expect(retry).toHaveAccessibleName(/try again/i);
    await expect(failure).toBeVisible();

    // Restored: the next retry recovers the screen itself.
    runSql("grant select on public.imprest_funding_position to authenticated;");
    await retry.click();
    await expect.poll(() => held.length).toBe(2);
    held[1]!();
    await expect(page.getByRole("heading", { name: /imprest funding/i }).first()).toBeVisible({
      timeout: 20_000,
    });
    await expect(failure).toHaveCount(0);
  } finally {
    for (const release of held) release();
    await page.unrouteAll({ behavior: "ignoreErrors" });
    runSql("grant select on public.imprest_funding_position to authenticated;");
  }
});
